"""Regenerate standard mapping data for codecs outside encoding_rs's WHATWG scope."""
from pathlib import Path
import hashlib
import re
import urllib.request

SOURCE = "https://raw.githubusercontent.com/unicode-org/icu-data/main/charset/data/ucm/ibm-1167_P100-2002.ucm"
ROOT = Path(__file__).resolve().parents[1] / "src"
SINGLE_BYTE = ["cp437", "cp850", "cp852", "cp857", "cp865", "cp1125", "iso8859_9", "iso8859_11", "koi8_t"]


def main() -> None:
    lines = [
        "// Generated by tools/generate_encodings.py from standard Unicode mappings.",
        "// SBCS and Big5 tables follow Python's standard codec registry; undefined entries are zero.",
        "// KOI8-RU follows Unicode ICU ibm-1167_P100-2002 (text_encoding_tables.LICENSE).",
        "",
    ]
    tables = {}
    for name in SINGLE_BYTE:
        values = []
        for byte in range(128, 256):
            try:
                values.append(ord(bytes([byte]).decode(name)))
            except UnicodeDecodeError:
                values.append(0)
        tables[name.upper().replace("_", "")] = values
    source = urllib.request.urlopen(SOURCE, timeout=30).read()
    assert hashlib.sha256(source).hexdigest() == "69f550f875c9d244bf3b53a721ace751735259cc23f19b330ab93480b1969ed9", "KOI8-RU source changed; review before regenerating"
    mappings = {int(byte, 16): int(char, 16) for char, byte in re.findall(r"<U([0-9A-F]+)> \\x([0-9A-Fa-f]{2}) \|0", source.decode())}
    assert len(mappings) == 256
    tables["KOI8RU"] = [mappings[byte] for byte in range(128, 256)]
    for name, values in tables.items():
        lines.append(f"pub(super) const {name}: [u32; 128] = [")
        for start in range(0, 128, 8):
            lines.append("    " + ", ".join(f"0x{value:04x}" for value in values[start:start + 8]) + ",")
        lines.append("];\n")
    (ROOT / "text_encoding_tables.rs").write_text("\n".join(lines))
    for codec, first, last, width in [("cp950", 0xA1, 0xFA, 2), ("big5hkscs", 0x81, 0xFF, 4)]:
        data = bytearray()
        sequences = []
        for lead in range(first, last):
            for trail in [*range(0x40, 0x7F), *range(0xA1, 0xFF)]:
                try:
                    chars = bytes([lead, trail]).decode(codec)
                    if len(chars) == 1:
                        value = ord(chars)
                    else:
                        value = 0x110000 + len(sequences)
                        sequences.append(chars)
                except UnicodeDecodeError:
                    value = 0
                data.extend(value.to_bytes(width, "little"))
        if codec == "big5hkscs":
            assert sequences == ["Ê\u0304", "Ê\u030c", "ê\u0304", "ê\u030c"]
        (ROOT / f"text_encoding_{codec}.bin").write_bytes(data)
    # GB2312 has different punctuation and unassigned slots from GBK.
    assigned = bytearray()
    for lead in range(0xA1, 0xF8):
        for trail in range(0xA1, 0xFF):
            try:
                value = ord(bytes([lead, trail]).decode("gb2312"))
                assigned.extend(value.to_bytes(2, "little"))
            except UnicodeDecodeError:
                assigned.extend(b"\0\0")
    (ROOT / "text_encoding_gb2312.bin").write_bytes(assigned)


if __name__ == "__main__":
    main()
